from html.parser import HTMLParser
import glob,re,os
class P(HTMLParser):
 def __init__(self): super().__init__(); self.title=[]; self.head=[]; self.text=[]; self.in_script=0; self.in_style=0
 def handle_starttag(self,t,a):
  if t=='title': self.title.append('')
  if t in ('h1','h2','h3','h4'): self.head.append((t,''))
  if t in ('script','style'): self.in_script+=1
 def handle_endtag(self,t):
  if t in ('script','style'): self.in_script=max(0,self.in_script-1)
 def handle_data(self,d):
  if self.in_script: return
  if self.title: self.title[-1]+=d
  if self.head and self.head[-1][0] in ('h1','h2','h3','h4'): self.head[-1]=(self.head[-1][0],self.head[-1][1]+d)
for f in glob.glob(os.environ['TMPDIR']+'/gla_*.html'):
 p=P(); p.feed(open(f,errors='ignore').read())
 print('\\n---',os.path.basename(f))
 print('title:', ' '.join(x.strip() for x in p.title))
 print('heads:', [(t,' '.join(x.split())) for t,x in p.head if x.strip()][:25])
